endpoint_functions.capture_mode:
static __always_inline unsigned long long capture_mode(void) {
  unsigned int zero = 0;
  unsigned long long *mode = bpf_map_lookup_elem(&capture_control, &zero);
  return mode ? *mode : 0;
}

endpoint_functions.current_capture_epoch:
static __always_inline unsigned long long current_capture_epoch(void) {
  return capture_mode() >> 1;
}

endpoint_functions.capture_enabled:
static __always_inline int capture_enabled(void) {
  struct endpoint_policy *p = get_policy();
  return p && p->capture_python && (capture_mode() & 1);
}

endpoint_functions.task_is_monitored_policy:
static __always_inline int
task_is_monitored_policy(const struct endpoint_policy *p,
                         unsigned long long pid) {
  if (!p || !p->enabled || pid == p->excluded_tgid)
    return 0;
  return !p->cgroup_id || task_under_cgroup(p->cgroup_id, p->cgroup_depth,
                                            p->cgroup_depth_valid);
}

endpoint_functions.task_is_monitored:
static __always_inline int task_is_monitored(void) {
  unsigned long long pid = bpf_get_current_pid_tgid() >> 32;
  return task_is_monitored_policy(get_policy(), pid);
}

endpoint_functions.lookup_python_binding:
static __always_inline struct python_binding *
lookup_python_binding(unsigned long long tid) {
  if (!capture_enabled())
    return 0;
  struct python_binding *binding = bpf_map_lookup_elem(&threads, &tid);
  if (!binding) {
    increment_diagnostic(PIDFD_DIAG_BINDING_UNAVAILABLE);
    return 0;
  }
  if (binding->birth != current_task_birth()) {
    increment_diagnostic(PIDFD_DIAG_BINDING_INVALIDATIONS);
    bpf_map_delete_elem(&threads, &tid);
    return 0;
  }
  return binding;
}

endpoint_functions.capture_python_source:
static __always_inline int capture_python_source(struct source_event *e) {
  if (clear_source(e)) {
    e->count = 0;
    e->flags = PIDFD_SOURCE_READ_ERROR;
    return -1;
  }
  unsigned long long tid = bpf_get_current_pid_tgid();
  e->pid_tid = tid;
  struct task_struct *task = (void *)bpf_get_current_task_btf();
  e->birth = BPF_CORE_READ(task, start_time);
  if (!task_is_monitored()) {
    e->flags = PIDFD_SOURCE_UNKNOWN;
    return 0;
  }
  struct python_binding *state = lookup_python_binding(tid);
  if (!state) {
    e->flags = PIDFD_SOURCE_UNKNOWN;
    return 0;
  }
  unsigned long long epoch = current_capture_epoch();
  struct walk_context walk = {.event = e, .code_type = python_code_type()};
  int failed = read_u64(state->state + 0, &walk.frame);
  if (failed)
    e->flags |= PIDFD_SOURCE_READ_ERROR;
  else
    bpf_loop(32, walk_frame, &walk, 0);
  if (walk.frame)
    e->flags |= PIDFD_SOURCE_STACK_TRUNCATED;
  if (!e->count)
    e->flags |= PIDFD_SOURCE_UNKNOWN;
  if (epoch != current_capture_epoch() || !capture_enabled()) {
    e->count = 0;
    e->flags = PIDFD_SOURCE_UNKNOWN;
  }
  return 0;
}

