static __always_inline int capture_state(struct source_event *out,
                                         unsigned long long state,
                                         char *line_buf,
                                         struct line_value *line_val) {
  if (clear_source(out))
    return -1;
  out->pid_tid = bpf_get_current_pid_tgid();
  struct task_struct *task = (void *)bpf_get_current_task_btf();
  out->birth = BPF_CORE_READ(task, start_time);
  struct fused_walk_context walk = {.out = out,
                                    .line_buf = line_buf,
                                    .line_val = line_val,
                                    .code_type = python_code_type()};
  int failed = warm_read(&walk.frame, 8, state + 0);
